import numpy as np

def mse(y, p):
    return float(((y - p) ** 2).mean())

def mae(y, p):
    return float(np.abs(y - p).mean())

def huber(y, p, delta=1.0):
    r = np.abs(y - p)
    quad = 0.5 * r ** 2
    lin = delta * (r - 0.5 * delta)
    return float(np.where(r <= delta, quad, lin).mean())

